    "analyzedInstructions": [
      {
        "name": "Base Preparation",
        "steps": [
          {
            "number": 1,
            "step": "Measure the whole dried figs and trim off any tough stems using kitchen shears before setting them in a large glass bowl."
          },
          {
            "number": 2,
            "step": "Halve the dried apricots and place them into the glass bowl together with the prepared figs to keep the dried fruit organized."
          },
          {
            "number": 3,
            "step": "Rinse the golden raisins under cool tap water in a fine strainer, then shake off the excess moisture before adding to the bowl."
          },
          {
            "number": 4,
            "step": "Pit the Medjool dates carefully and chop each date into three equal pieces so they dissolve slightly during the long cook."
          },
          {
            "number": 5,
            "step": "Add the dried prunes to the fruit mixture and toss everything thoroughly until the assorted dried fruits are evenly distributed."
          },
          {
            "number": 6,
            "step": "In a separate small skillet, toast the blanched almonds over low heat until they turn pale golden and smell visibly fragrant."
          },
          {
            "number": 7,
            "step": "Transfer the warm almonds onto a parchment sheet to cool completely before chopping them coarsely with a chef knife."
          },
          {
            "number": 8,
            "step": "Shell the raw pistachios and rub off the excess skins using a clean cotton towel before chopping them into small fragments."
          },
          {
            "number": 9,
            "step": "Spread the walnut halves across a small rimmed tray and roast them in a warm oven for six minutes until lightly toasted."
          },
          {
            "number": 10,
            "step": "Zest the clementines using a microplane, taking care to extract only the sweet orange outer peel without bitter white pith."
          },
          {
            "number": 11,
            "step": "Squeeze fresh sweet orange juice through a fine mesh strainer to collect two cups of clear citrus juice for the poaching broth."
          },
          {
            "number": 12,
            "step": "Measure the clear honey into a glass measuring pitcher and warm it slightly to allow for smooth pouring into the pot."
          },
          {
            "number": 13,
            "step": "Combine the orange juice, rose water, and orange blossom water together in a small jug to form the fragrant liquid base."
          },
          {
            "number": 14,
            "step": "Crush the saffron threads gently between your fingers into a small pinch cup and soak them in warm water for ten minutes."
          }
        ]
      },
      {
        "name": "Stewing and Simmering",
        "steps": [
          {
            "number": 1,
            "step": "Melt the unsalted butter in a heavy tagine base over medium heat until it bubbles gently without taking on any brown color."
          },
          {
            "number": 2,
            "step": "Add the cinnamon sticks, whole cloves, star anise, and ground cardamom to the warm butter to bloom the spices briefly."
          },
          {
            "number": 3,
            "step": "Stir in the ground ginger and ground nutmeg, tossing constantly with a wooden spoon for thirty seconds until highly aromatic."
          },
          {
            "number": 4,
            "step": "Pour the sweetened citrus and floral liquid mixture into the tagine, stirring constantly to melt the spice deposits completely."
          },
          {
            "number": 5,
            "step": "Whisk the clear honey and dark pomegranate molasses directly into the simmering liquid until fully blended and translucent."
          },
          {
            "number": 6,
            "step": "Add the soaked saffron threads along with their golden steeping liquid into the tagine, stirring to combine all liquids."
          },
          {
            "number": 7,
            "step": "Carefully transfer all of the mixed dried fruits into the simmering spice liquid, arranging them in a uniform layer."
          },
          {
            "number": 8,
            "step": "Cover the tagine with its conical lid and reduce the heat to low, maintaining a very gentle and steady simmer throughout."
          },
          {
            "number": 9,
            "step": "Cook the fruit stew covered for twenty minutes, allowing the dried fruits to absorb the hot liquid and swell in volume."
          },
          {
            "number": 10,
            "step": "Remove the lid and use a wide spoon to baste the top layer of fruit with the rich, bubbling spiced syrup in the pan."
          },
          {
            "number": 11,
            "step": "Replace the lid and continue simmering for another fifteen minutes until the fruits become remarkably soft and glossy."
          },
          {
            "number": 12,
            "step": "Check the liquid level and add two tablespoons of water if the syrup appears too thick before finalizing the fruit cook."
          },
          {
            "number": 13,
            "step": "Scatter half of the toasted blanched almonds into the simmering stew to absorb the warm floral flavours of the broth."
          },
          {
            "number": 14,
            "step": "Simmer uncovered for five final minutes so the poaching liquid reduces into a thick, glossy syrup coating the soft fruits."
          }
        ]
      },
      {
        "name": "Dessert Finishing",
        "steps": [
          {
            "number": 1,
            "step": "Extinguish the cooktop heat and allow the tagine to sit undisturbed for ten minutes so the deep flavours meld together."
          },
          {
            "number": 2,
            "step": "Pick fresh mint leaves from their stems, discarding any wilted leaves, and slice them into thin, delicate ribbons."
          },
          {
            "number": 3,
            "step": "Extract vibrant red seeds from a ripe pomegranate, discarding any white membrane, and reserve them in a small cup."
          },
          {
            "number": 4,
            "step": "Lightly toast the sesame seeds in a dry pan over low heat for two minutes until lightly browned and nutty in aroma."
          },
          {
            "number": 5,
            "step": "Arrange four decorative shallow ceramic dessert bowls across a clean work surface ready for final plated assembly."
          },
          {
            "number": 6,
            "step": "Carefully remove the whole cinnamon sticks and star anise pods from the tagine using long kitchen tongs and discard."
          },
          {
            "number": 7,
            "step": "Ladle equal portions of the warm stewed fruits into each prepared ceramic dessert bowl using a heatproof slotted spoon."
          },
          {
            "number": 8,
            "step": "Spoon generous amounts of the reduced golden syrup over the plated fruits until each serving is thoroughly coated."
          },
          {
            "number": 9,
            "step": "Garnish each dessert bowl with the remaining toasted blanched almonds, placing them neatly around the fruit mound."
          },
          {
            "number": 10,
            "step": "Sprinkle the chopped raw pistachios and toasted walnut pieces over the top of each fruit portion for color and crunch."
          },
          {
            "number": 11,
            "step": "Scatter the toasted sesame seeds lightly across the hot fruits to provide a delicate nutty aroma to every bowl."
          },
          {
            "number": 12,
            "step": "Distribute the bright pomegranate seeds over the warm dessert bowls to add a refreshing pop of color and acidity."
          },
          {
            "number": 13,
            "step": "Finish each plate with a scattering of fresh mint ribbons, adding a vibrant green accent to the finished dessert."
          },
          {
            "number": 14,
            "step": "Serve the warm Moroccan fruit stew immediately alongside a hot pot of fresh mint tea to complete the dessert course."
          }
        ]
      }
    ]
  }
]
